#!/usr/bin/env bash
#
# Show the latest AI-NER full test result generated by:
#
#   ./scripts/test-docker-host-user.sh
#
# This script is read-only. It does not run tests, modify files, stage files,
# commit files, push files, or delete files.
#
# Expected result files:
#
#   .test-results/latest-full-test.md
#   .test-results/latest-full-test.json
#
# Usage:
#
#   ./scripts/show-latest-test-result.sh
#
# Optional:
#
#   ./scripts/show-latest-test-result.sh --json
#   ./scripts/show-latest-test-result.sh --markdown
#   ./scripts/show-latest-test-result.sh --summary
#
# Notes:
#
# - The authoritative full test must be run from Rui's macOS host terminal:
#
#     ./scripts/test-docker-host-user.sh
#
# - Hermes may read the generated .test-results/ files.
# - .test-results/ is generated local output and must not be committed.

set -euo pipefail

RESULT_DIR=".test-results"
MD_FILE="${RESULT_DIR}/latest-full-test.md"
JSON_FILE="${RESULT_DIR}/latest-full-test.json"

MODE="summary"

usage() {
  cat <<'EOF'
Usage:
  ./scripts/show-latest-test-result.sh [--summary|--markdown|--json|--help]

Options:
  --summary    Show a compact summary from the latest JSON/Markdown result. Default.
  --markdown   Print .test-results/latest-full-test.md.
  --json       Print .test-results/latest-full-test.json.
  --help       Show this help message.

This script is read-only. It does not run tests.

The authoritative full test result should be generated by Rui from the macOS
host terminal with:

  ./scripts/test-docker-host-user.sh

That command should write:

  .test-results/latest-full-test.md
  .test-results/latest-full-test.json
EOF
}

if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  usage
  exit 0
fi

if [ "${1:-}" = "--markdown" ]; then
  MODE="markdown"
elif [ "${1:-}" = "--json" ]; then
  MODE="json"
elif [ "${1:-}" = "--summary" ] || [ -z "${1:-}" ]; then
  MODE="summary"
else
  echo "ERROR: Unknown option: ${1}" >&2
  echo >&2
  usage >&2
  exit 2
fi

if [ ! -d "${RESULT_DIR}" ]; then
  cat >&2 <<EOF
ERROR: ${RESULT_DIR}/ does not exist.

No latest generated test result was found.

Run this from the macOS host terminal first:

  ./scripts/test-docker-host-user.sh

Then run this script again:

  ./scripts/show-latest-test-result.sh
EOF
  exit 1
fi

if [ "${MODE}" = "markdown" ]; then
  if [ ! -f "${MD_FILE}" ]; then
    echo "ERROR: ${MD_FILE} does not exist." >&2
    exit 1
  fi
  cat "${MD_FILE}"
  exit 0
fi

if [ "${MODE}" = "json" ]; then
  if [ ! -f "${JSON_FILE}" ]; then
    echo "ERROR: ${JSON_FILE} does not exist." >&2
    exit 1
  fi
  cat "${JSON_FILE}"
  printf '\n'
  exit 0
fi

# Summary mode.
echo "# Latest AI-NER Test Result"
echo

if [ -f "${JSON_FILE}" ]; then
  # Use Python for robust JSON parsing because macOS does not always have jq.
  python3 - "${JSON_FILE}" <<'PY'
import json
import sys
from pathlib import Path

path = Path(sys.argv[1])

try:
    data = json.loads(path.read_text(encoding="utf-8"))
except Exception as exc:
    print(f"ERROR: Could not parse {path}: {exc}", file=sys.stderr)
    sys.exit(1)

def value(key: str, default: str = "not recorded"):
    item = data.get(key, default)
    if item is None or item == "":
        return default
    return item

timestamp = value("timestamp")
status = value("status")
pytest_exit_code = value("pytest_exit_code")
test_summary = value("test_summary")
coverage_percent = value("coverage_percent")
coverage_gate = value("coverage_gate")
repository = value("repository")
branch = value("branch")
commit = value("commit")
docker_image = value("docker_image")
host_uid = value("host_uid")
host_gid = value("host_gid")
command = value("command")
pytest_args = value("pytest_args", "<none>")
log_file = value("log_file")
clean_log_file = value("clean_log_file")

if isinstance(coverage_percent, (int, float)):
    coverage_text = f"{coverage_percent:.2f}%"
else:
    coverage_text = str(coverage_percent)

print("## Summary")
print()
print(f"- Timestamp: {timestamp}")
print(f"- Status: {status}")
print(f"- Pytest exit code: {pytest_exit_code}")
print(f"- Test summary: {test_summary}")
print(f"- Coverage: {coverage_text}")
print(f"- Coverage gate: {coverage_gate}")
print()
print("## Environment")
print()
print(f"- Repository: {repository}")
print(f"- Branch: {branch}")
print(f"- Commit: {commit}")
print(f"- Docker image: {docker_image}")
print(f"- Host UID:GID: {host_uid}:{host_gid}")
print()
print("## Command")
print()
print("```bash")
print(command)
print("```")
print()
print("## Pytest arguments")
print()
print("```text")
print(pytest_args)
print("```")
print()
print("## Log files")
print()
print(f"- Full log: `{log_file}`")
print(f"- Clean log: `{clean_log_file}`")
print()
print("## Interpretation")
print()

if status == "passed":
    print("Functional tests pass and the coverage gate passes.")
elif status == "failed_coverage_gate":
    print("Functional tests pass, but the full command exits non-zero because the coverage gate fails.")
elif status == "failed_before_pytest":
    print("The command failed before pytest produced a test result. The previous authoritative baseline remains unchanged.")
elif status == "failed":
    print("One or more tests failed, or the result could not be classified as a coverage-only failure.")
else:
    print("Status is not recognized. Inspect the Markdown and log files before updating testing-status.md.")
PY
  exit 0
fi

if [ -f "${MD_FILE}" ]; then
  echo "JSON result file not found:"
  echo
  echo "  ${JSON_FILE}"
  echo
  echo "Showing Markdown result instead:"
  echo
  cat "${MD_FILE}"
  exit 0
fi

cat >&2 <<EOF
ERROR: No latest result file found.

Expected at least one of:

  ${JSON_FILE}
  ${MD_FILE}

Run this from the macOS host terminal first:

  ./scripts/test-docker-host-user.sh
EOF

exit 1
